int main(int argc,char**argv){if(argc!=2)return 2;try{static_assert(sizeof(knode)==2068);static_assert(offsetof(knode,indices)==4);static_assert(offsetof(knode,keys)==1032);static_assert(offsetof(knode,is_leaf)==2060);static_assert(offsetof(knode,num_keys)==2064);std::ofstream out(argv[1],std::ios::binary);int32_t nc=3;out.write((char*)&nc,4);for(int N:{17,4096,65536}){node*root=nullptr;size=N;order=256;for(int j=0;j<N;j++){int i=(int)((long long)j*8191%N),key=3*i-2*N;root=insert(root,key,key*7+3);}long used=transform_to_cuda(root,false);int32_t nn=(used-N*sizeof(record))/sizeof(knode),h=height(root),q=N==17?33:N==4096?257:1024;printf("FIXTURE records=%d nodes=%d height=%d queries=%d\n",N,nn,h,q);int32_t hdr[4]={N,nn,h,q};out.write((char*)hdr,16);std::vector<knode>clean(nn);for(int j=0;j<nn;j++){memset(&clean[j],0,sizeof(knode));clean[j].location=knodes[j].location;clean[j].is_leaf=knodes[j].is_leaf;clean[j].num_keys=knodes[j].num_keys;for(int l=0;l<257;l++)clean[j].keys[l]=INT_MAX;for(int l=0;l<knodes[j].num_keys;l++){clean[j].keys[l]=knodes[j].keys[l];clean[j].indices[l]=knodes[j].indices[l];}if(clean[j].num_keys<2||clean[j].num_keys>257)throw std::runtime_error("nodekeys");for(int l=1;l<clean[j].num_keys;l++)if(clean[j].keys[l]<=clean[j].keys[l-1])throw std::runtime_error("nonstrictkeys");if(!clean[j].is_leaf)for(int l=0;l<clean[j].num_keys-1;l++)if(clean[j].indices[l]<0||clean[j].indices[l]>=nn)throw std::runtime_error("childrange");}out.write((char*)clean.data(),nn*sizeof(knode));for(int i=0;i<N;i++)if(krecords[i].value!=(3*i-2*N)*7+3)throw std::runtime_error("recordorder");out.write((char*)krecords,N*sizeof(record));std::vector<int32_t>keys(q),start(q),end(q);for(int j=0;j<q;j++){int i=(j*941)%N;if(j==1)i=N-1;if(j==2)i=0;keys[j]=3*i-2*N+(j%4==0?1:0);record*r=find(root,keys[j],false);if((j%4==0&&r)||(j%4!=0&&(!r||r->value!=keys[j]*7+3)))throw std::runtime_error("sourceCPUlookup");int a=(j*613)%N,b=std::min(N-1,a+j%23);if(j%7==0){a=0;b=N-1;}if(j%7==1){a=std::max(0,N-129);b=N-1;}if(j%7==2)b=a;start[j]=3*a-2*N;end[j]=3*b-2*N;}out.write((char*)keys.data(),q*4);out.write((char*)start.data(),q*4);out.write((char*)end.data(),q*4);free(mem);root=destroy_tree(root);}return !out;}catch(std::exception&e){fprintf(stderr,"FIXTURE_FAIL %s\n",e.what());return 1;}}
